{"command": "perl - <<'PERL'
use strict;
use warnings;
my %seqs; my $name;
while(<>) {
  chomp; if(/^>(\S+)/){$name=$1; $seqs{$name}=''; next;} $seqs{$name}.=uc $_; }
my $out=$seqs{output};
my $pref=214; my $suff=2040; my $insert=substr($out,$pref,length($out)-$pref-$suff);
my $flag=$seqs{flag};
my $best=-1; my $bestpos=-1;
for my $pos (0..(length($insert)-length($flag))){
  my $sub=substr($insert,$pos,length($flag));
  my $match=0;
  for my $i (0..length($flag)-1){
    $match++ if substr($sub,$i,1) eq substr($flag,$i,1);
  }
  if($match>$best){$best=$match;$bestpos=$pos;}
}
print "best match flag pos $bestpos match $best/",length($flag),"\n";
my $sub=substr($insert,$bestpos,length($flag));
print "flag sub at pos:$sub\n";
PERL
"}

