{"command": "perl - <<'PERL'
use strict;use warnings;my %s; my $n; open my $fh,'<','sequences.fasta' or die $!; while(<$fh>){chomp; if(/^>(\S+)/){$n=$1;$s{$n}=''; next;} $s{$n}.=uc $_;} close $fh;
