my $best=-1; my $bestpos=-1; my $bestmm=0;
for my $pos (0..length($insert)-$len){
  my $sub=substr($insert,$pos,$len); my $mm=0;
  for my $i (0..$len-1){$mm++ if substr($sub,$i,1) ne substr($flag,$i,1);} 
  if($best==-1 || $mm<$best){$best=$mm;$bestpos=$pos; $bestmm=$mm;}
