print "insert segment:", $sub, "\n";
# report mismatches
for my $i (0..$len-1){
  my $a=substr($sub,$i,1); my $b=substr($flag,$i,1);
  if($a ne $b){print "mismatch at $i insert $a flag $b\n";}
}
PERL
"}

